import random
import itertools

def is_3_colorable(n, edges):
    # Backtracking coloring
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1]*n
    # order vertices by degree descending for pruning
    order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)
    pos = {v:i for i,v in enumerate(order)}

    def dfs(i):
        if i == n:
            return True
        v = order[i]
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(i+1):
                    return True
                colors[v] = -1
        return False

    return dfs(0)

def check_graph(edges):
    n = 8
    deg = [0]*n
    for u,v in edges:
        deg[u] += 1
        deg[v] += 1
    if any(d < 3 or d > 4 for d in deg):
        return False
    e = len(edges)
    if not (13 <= e <= 16):
        return False
    if not is_3_colorable(n, edges):
        return False
    return True

fixed = {(0,7), (1,7)}
remaining = [(u,v) for u in range(8) for v in range(u+1,8) if (u,v) not in fixed]

random.seed(0)
for trial in range(200000):
    # choose number of additional edges
    add = random.randint(11,14)
    extra = random.sample(remaining, add)
    edges = list(fixed) + extra
    if check_graph(edges):
        print("Found!")
        print(sorted(edges))
        print("Edges:", len(edges))
        print("Degrees:", [sum(1 for u,v in edges if u==i or v==i) for i in range(8)])
